(*
  Following features are application controlled using product specific HW diagnostic program:
  - Safety switch startup test
  - Safety switch (output group 1) control

  Following example can be used for controlling. Add application specific conditions.
*)
// Safety switch startup test trigger. Add a system specific delay if necessary.
// For example, if there are voltage fluctuations during system startup.
EPEC_HWDIAG.S_CORE1MCU_Diagnostic.i_SwitchStartupTestEnable := TRUE;

// Safety switch control
EPEC_HWDIAG.S_CORE1MCU_Diagnostic.i_OutputGroup1Control := G_StatusFlags_Safe.S_SafeOperationEnable;

(* HW diagnostic program contains supply voltage states for different control types which are used by application
  Example:
	output1 := control AND // application control
				G_StatusFlags_Safe.S_SafeOperationEnable AND // common diagnostic OK conditions
				EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_SupplyVoltageEnableStates.SafeControl; // supply voltage in safe control operational range
*)

// For more information, see Epec programming manual's How to guides.
